import unittest
from candidate import largest_divisor

class TestLargestDivisor(unittest.TestCase):

    def test_largest_divisor_positive_integer(self):
        self.assertEqual(largest_divisor(15), 5)
        self.assertEqual(largest_divisor(21), 7)
        self.assertEqual(largest_divisor(28), 14)

    def test_largest_divisor_odd_number(self):
        self.assertEqual(largest_divisor(15), 5)
        self.assertEqual(largest_divisor(21), 7)
        self.assertEqual(largest_divisor(25), 5)

    def test_largest_divisor_even_number(self):
        self.assertEqual(largest_divisor(16), 8)
        self.assertEqual(largest_divisor(28), 14)
        self.assertEqual(largest_divisor(20), 10)

    def test_largest_divisor_prime_number(self):
        self.assertEqual(largest_divisor(13), 1)
        self.assertEqual(largest_divisor(17), 1)

    def test_largest_divisor_power_of_two(self):
        self.assertEqual(largest_divisor(8), 4)
        self.assertEqual(largest_divisor(16), 8)

    def test_largest_divisor_one(self):
        self.assertEqual(largest_divisor(1), 1)

    def test_largest_divisor_self(self):
        self.assertEqual(largest_divisor(5), 1)

    def test_largest_divisor_negative_number(self):
        self.assertEqual(largest_divisor(-15), -1)

    def test_largest_divisor_zero(self):
        with self.assertRaises(ValueError):
            largest_divisor(0)

    def test_largest_divisor_non_integer(self):
        with self.assertRaises(TypeError):
            largest_divisor(2.5)

if __name__ == '__main__':
    unittest.main()
